const item = $input.first().json;

return [{
  json: {
    id: item.id,
    step_id: item.step_id,
    question: item.questions,

    validation:
      item.validation ??
      item.validation_rule ??
      item.Validation_table ??
      null,

    buttons: [
      item.Button1,
      item.Button2,
      item.Button3,
      item.Button4,
      item.Button5
    ].filter(Boolean),

    createdAt: item.createdAt,
    updatedAt: item.updatedAt
  }
}];

// WhatsApp Message

const msg = $("WhatsApp Trigger").first().json.messages[0];

// Text Input
const input = (
    msg?.text?.body ??
    msg?.interactive?.button_reply?.title ??
    msg?.interactive?.list_reply?.title ??
    ""
)
.trim()
.toLowerCase();

// List Reply ID
const listId = (
    msg?.interactive?.list_reply?.id ??
    ""
)
.trim()
.toLowerCase();

// =========================
// Restart
// =========================

const restart =
    listId === "restart" ||
    [
        "restart",
        "start over",
        "start again",
        "reset",
        "menu",
        "home"
    ].some(k => input.includes(k));

// =========================
// Human Support
// =========================

const support =
    listId === "escalation" ||
    [
        "human",
        "support",
        "agent",
        "representative",
        "talk to human",
        "live agent",
        "customer support",
        "escalate"
    ].some(k => input.includes(k));

// =========================
// Normal Buttons
// =========================

const buttons = [
    $json.Button1,
    $json.Button2,
    $json.Button3,
    $json.Button4
]
.filter(v => v && String(v).toLowerCase() !== "null")
.map(v => String(v).trim().toLowerCase());
// Agar restart ya support hua to validation ki zarurat nahi
const valid = restart || support || buttons.includes(input);

// Response
let response = "";

if (restart) {
    response = "Restarting the conversation...";
}
else if (support) {
    response = "Connecting you with our support team...";
}
else if (!buttons.includes(input)) {
    response = `Please choose one of the available options:\n\n${buttons.join("\n")}`;
}

return [{
    json: {
        valid,
        extracted_information: buttons.includes(input) ? input : "",
        responseToUser: response,
        escalate_to_support: support,
        restart: restart
    }
}];

