// WhatsApp Message
const trigger = $("WhatsApp Trigger").first().json;

if (!trigger.messages) {
  return [];
}

const msg = trigger.messages[0];

// User Input
const input = (
  msg?.text?.body ??
  msg?.interactive?.button_reply?.title ??
  msg?.interactive?.list_reply?.title ??
  ""
).trim().toLowerCase();

// Allowed Options
const options = ["buy", "rent", "sell"];

// Validation
const valid = options.includes(input);

// Intent
const intent = valid
  ? input.charAt(0).toUpperCase() + input.slice(1)
  : "";

return [{
  json: {
    valid,
    Intent: intent,
    extracted_information: valid ? input : "",
    responseToUser: valid ? "" : "",
    escalate_to_support: false,
    restart: false
  }
}];

